.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: var(--biss-control-height);
  height: var(--biss-control-height);
  padding: 0 12px;
  border: 1px solid var(--biss-primary);
  border-radius: var(--biss-radius-sm);
  background: var(--biss-primary);
  color: #fff;
  font: 500 13.5px/1.2 var(--biss-font-family);
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  box-shadow: var(--biss-shadow);
  transition:
    background 0.15s,
    border-color 0.15s;
}
.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: var(--biss-control-height);
  height: var(--biss-control-height);
  padding: 0 12px;
  border: 1px solid var(--biss-primary);
  border-radius: var(--biss-radius-sm);
  background: var(--biss-primary);
  color: #fff;
  font: 500 13.5px/1.2 var(--biss-font-family);
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  box-shadow: var(--biss-shadow);
  transition:
    background 0.15s,
    border-color 0.15s;
}
.ds-button:hover:not(:disabled):not([aria-disabled='true']) {
  background: var(--biss-primary-hover);
  border-color: var(--biss-primary-hover);
}
.ds-button:disabled, .ds-button[aria-disabled='true'] {
  opacity: 0.5;
  cursor: default;
  pointer-events: none;
}
.ds-button {
    transition: none;
  }
.ds-button:focus-visible,.ds-nav-item:focus-visible{outline:2px solid var(--biss-primary);outline-offset:2px;}
@media(prefers-reduced-motion:reduce){.ds-button{transition:none}}

