.ds-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  color: var(--biss-text);
  font: 13.5px/1.5 var(--biss-font-family);
}
.ds-field-label {
  display: block;
  font-size: 13px;
  font-weight: 500;
}
.ds-input {
  display: block;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  height: var(--biss-control-height);
  padding: 0 10px;
  border: 1px solid var(--biss-border-strong);
  border-radius: var(--biss-radius-sm);
  background: var(--biss-card);
  color: var(--biss-text);
  font: 400 13.5px/1.5 var(--biss-font-family);
  box-shadow: none;
  transition: border-color 0.15s;
}
.ds-input::placeholder {
  color: var(--biss-muted);
}
.ds-input:focus {
  outline: 2px solid var(--biss-primary);
  outline-offset: 1px;
  border-color: var(--biss-primary);
}
.ds-input[aria-invalid='true'] {
  border-color: var(--biss-danger);
}
.ds-input:disabled {
  opacity: 0.5;
  cursor: default;
}
.ds-input {
    transition: none;
  }
@media(prefers-reduced-motion:reduce){.ds-input{transition:none}}

.ds-nav-item {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding: 5px 10px;
  border-radius: 7px;
  color: var(--biss-muted);
  font: 400 13px/1.5 var(--biss-font-family);
  text-decoration: none;
}
.ds-nav-item:hover {
  background: var(--biss-hover);
  color: var(--biss-text);
}
.ds-nav-item.is-active {
  background: var(--biss-info-bg);
  color: var(--biss-primary);
  font-weight: 500;
}.ds-button:focus-visible,.ds-nav-item:focus-visible{outline:2px solid var(--biss-primary);outline-offset:2px;}

.ds-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 22px;
  padding: 1px 8px;
  border: 1px solid var(--biss-border);
  border-radius: 11px;
  background: var(--biss-surface-subtle);
  color: var(--biss-muted);
  font: 500 12px/1.4 var(--biss-font-family);
  text-transform: none;
  letter-spacing: normal;
  white-space: nowrap;
}
.ds-badge-success {
  background: var(--biss-success-bg);
  color: var(--biss-success);
  border-color: var(--biss-success-border);
}

.ds-card {
  background: var(--biss-card);
  color: var(--biss-text);
  border: 1px solid var(--biss-border);
  border-radius: var(--biss-radius-md);
  box-shadow: var(--biss-shadow);
  min-width: 0;
}
.ds-card-padded {
  padding: 20px 22px;
}
.ds-card{font-family:var(--biss-font-family, "Inter Variable", "Inter", system-ui, -apple-system, "Segoe UI", sans-serif);font-size:14px;line-height:1.55;}
